#!/bin/zsh
# Calibration review (K-19): pass-1 blind review of one synthetic candidate on a
# calib/<ID> branch. Ground truth is never in the brief. Writes the verdict line
# and findings to work/calib/<ID>.json. Must not run while run-task.sh is waiting
# on the inbox (shared Run inbox).
set -u
ID=${1:?calibration id}; FN=${2:?function name under review}; ACS=${3:?comma-separated AC ids}
S=/Users/oliverharoun/Sites/agent-orchestration/spike; T=/Users/oliverharoun/Sites/agent-orchestration/tools/sdd.mjs; F=$HOME/Sites/orca-sdd-fixture; PACK=$F/.agents/orca-sdd
C=$(cat $S/.coordinator-handle); LOG=$(cat $S/.p3-log); RUN=$(cat $S/.p5-run); REPO=id:e39c9174-87d1-44c6-9cb0-fa6488a7a3c4; W=$S/p5/work/calib; mkdir -p "$W"
die(){ echo "STOP [calib $ID] $1"; exit 1; }
js(){ python3 -I -c "import json,sys; d=json.load(open(sys.argv[1])); print($2)" "$1"; }
BASE=1c6397c740d9b64fab471a40f493c6f6acd10bcc; CAND=$(git -C "$F" rev-parse "calib/$ID") || die "branch"
SPEC_H=$(node "$T" doc-identity --repo "$F" --revision "$BASE" --path specs/pilot/spec.md | js /dev/stdin 'd["sha256"]'); PLAN_H=$(node "$T" doc-identity --repo "$F" --revision "$BASE" --path specs/pilot/plan.md | js /dev/stdin 'd["sha256"]'); PACK_H=$(node "$T" pack-hash --dir "$PACK" | js /dev/stdin 'd["hash"]')
git -C "$F" show "${BASE}:specs/pilot/spec.md" > "$W/spec.md"
RV=$(orca worktree create --repo $REPO --name "calib-$ID" --no-parent --base-branch "calib/$ID" --setup skip --json | python3 -I -c 'import json,sys; d=json.load(sys.stdin); print(d["result"]["worktree"]["path"] if d.get("ok") else "")'); [ -n "$RV" ] || die "worktree"; git -C "$RV" checkout -q --detach "$CAND"; [ "$(git -C "$RV" rev-parse HEAD)" = "$CAND" ] || die "detach"
python3 -I - "$ID" "$FN" "$ACS" "$F" "$RV" "$BASE" "$CAND" "$SPEC_H" "$PLAN_H" "$PACK_H" "$LOG" > "$W/$ID-brief.json" <<'EOF' || exit 1
import json,sys
ID,FN,ACS,F,RV,BASE,CAND,SPEC_H,PLAN_H,PACK_H,LOG=sys.argv[1:12]
b={"schema_version":"1","identity":{"brief_id":"brief_pilot_calib_"+ID+"_p1","role":"reviewer","mode":"M-2"},
 "objective":{"outcome":"Independent pass-1 review of candidate "+CAND[:12]+" which adds "+FN+"() and its tests, against specs/pilot/spec.md shared rules R-1 to R-5 and "+ACS.replace(","," and ")+".","ac_ids":ACS.split(","),"exclusions":["No edits.","Do not read .agents/, .agent-task.md, audit logs or any implementer narrative."],"expected_result":"VERDICT line first, then per-criterion verdicts with file and line, findings with severity and verification step, checks run with result lines."},
 "context":{"feature_spec":{"path":"specs/pilot/spec.md","baseline":"approved","revision":BASE,"sha256":SPEC_H},"feature_plan":{"path":"specs/pilot/plan.md","baseline":"approved","revision":BASE,"sha256":PLAN_H},"role_pack_hash":PACK_H,"instructions":["AGENTS.md"],"evidence":["git diff "+BASE[:12]+".."+CAND[:12]+" (run it yourself; read-only git commands are permitted)"],"predecessor_conclusions":["'clamp respects upper bound' fails by design until task T5; not a finding unless the candidate changed clamp.","The candidate's own tests may be incomplete; judge the implementation against the spec, not only against the tests it ships.","Your worker_done body MUST start with exactly one of these lines: 'VERDICT: ACCEPT' (no findings, or only low findings) or 'VERDICT: REPAIR' (at least one medium or higher finding). Then the per-criterion verdicts, findings, checks run, uncertainty."]},
 "workspace":{"repository":F,"integration_checkout":F,"worker_checkout":RV,"base_sha":BASE,"candidate_sha":CAND,"dirty_state":None,"assigned_paths":[],"new_paths":[],"protected_paths":[]},
 "execution":{"runtime":"codex","model":"gpt-6-astra","effort":"high","permission_recipe":"codex-read-only","readiness":{"setup_complete":True},"limits":{"session_minutes":20,"attempts":1,"max_files":5,"max_lines":300},"retrieval":[]},
 "validation":{"checks":[{"name":FN+" tests","command":"node --test --test-name-pattern=\"^"+FN+"\" test/","expected":"all "+FN+" tests ok"},{"name":"full suite","command":"npm test","expected":"only 'clamp respects upper bound' fails"}],"estimate":{"files":0,"lines":0},"generated_paths":[],"scratch_paths":[],"fixture_only":True},
 "delivery":{"result_fields":["VERDICT line","candidate SHA inspected","pass number","per-criterion verdicts","findings","checks run","remaining uncertainty"],"reply_route":"Orca run inbox via the injected preamble (worker_done once)","usage_source":"codex-session-rollout","budget_ref":"pilot-calibration","escalation_rule":"BLOCKED_CONTEXT if HEAD is not the candidate SHA","recovery_ref":".agent-task.md (coordinator only)","audit_ref":LOG,"pass":1,"pass_one_exclusions":["implementer self-report","claimed check results","advisor output","prior verdicts","plan rationale","recovery and audit files"]}}
print(json.dumps(b,indent=1))
EOF
node "$T" brief-validate "$W/$ID-brief.json" > "$W/$ID-validate.json" || { cat "$W/$ID-validate.json"; die "brief"; }; BH=$(js "$W/$ID-validate.json" 'd["identities"]["brief_hash"]')
node "$T" brief-render --brief "$W/$ID-brief.json" --role-file "$PACK/roles/reviewer.md" --spec-excerpt "$W/spec.md" --out "$W/$ID-prompt.txt" > "$W/$ID-render.json" || die render; PH=$(js "$W/$ID-render.json" 'd["prompt_hash"]')
node "$T" audit-append --log "$LOG" --type brief_validated --json "{\"run_id\":\"$RUN\",\"task_ref\":\"calibration $ID\",\"brief_id\":\"brief_pilot_calib_${ID}_p1\",\"brief_hash\":\"$BH\",\"role\":\"reviewer\",\"candidate_sha\":\"$CAND\",\"feature_spec_sha256\":\"$SPEC_H\",\"feature_plan_sha256\":\"$PLAN_H\",\"calibration\":true}" >/dev/null
node "$T" audit-append --log "$LOG" --type dispatch_intent --json "{\"run_id\":\"$RUN\",\"task_ref\":\"calibration $ID\",\"brief_id\":\"brief_pilot_calib_${ID}_p1\",\"brief_hash\":\"$BH\",\"prompt_hash\":\"$PH\",\"role\":\"reviewer\",\"runtime\":\"codex\",\"worker_checkout\":\"$RV\",\"candidate_sha\":\"$CAND\",\"calibration\":true}" >/dev/null
XH=$(orca terminal create --worktree "path:$RV" --title "calib-$ID" --command 'codex --sandbox read-only --model gpt-6-astra -c model_reasoning_effort="high"' --json | python3 -I -c 'import json,sys; d=json.load(sys.stdin); print(d["result"]["terminal"]["handle"] if d.get("ok") else "")'); [ -n "$XH" ] || die terminal
for i in 1 2 3 4 5; do B=$(orca terminal wait --terminal "$XH" --for tui-idle --timeout-ms 45000 --json | python3 -I -c 'import json,sys; d=json.load(sys.stdin); w=d["result"]["wait"]; print("idle" if w.get("satisfied") else (w.get("blockedReason") or "unknown"))'); case "$B" in idle) break;; agent-update-prompt) orca terminal send --terminal "$XH" --text "2" --json >/dev/null;; agent-trust-workspace) orca terminal send --terminal "$XH" --text "" --enter --json >/dev/null;; *) sleep 3;; esac; done; [ "$B" = idle ] || die "codex idle"
START=$(date -u +%Y-%m-%dT%H:%M:%SZ); TK=$(orca orchestration task-create --from "$C" --run $RUN --task-title "pilot calibration $ID" --spec "$(cat "$W/$ID-prompt.txt")" --json | python3 -I -c 'import json,sys; d=json.load(sys.stdin); r=d.get("result",d); t=r.get("task",r); print(t.get("id") if d.get("ok") else "")'); [ -n "$TK" ] || die task
orca orchestration worker-start --from "$C" --run $RUN --task "$TK" --worktree "path:$RV" --terminal "$XH" --timeout-ms 60000 --json > "$W/$ID-start.json" 2>&1 || true; DP=$(python3 -I -c 'import json,sys; d=json.load(open(sys.argv[1])); print(d["result"]["dispatchId"] if d.get("ok") else "")' "$W/$ID-start.json"); [ -n "$DP" ] || die "worker-start"
node "$T" audit-append --log "$LOG" --type dispatch_started --json "{\"run_id\":\"$RUN\",\"task_id\":\"$TK\",\"dispatch_id\":\"$DP\",\"brief_id\":\"brief_pilot_calib_${ID}_p1\",\"brief_hash\":\"$BH\",\"prompt_hash\":\"$PH\",\"role\":\"reviewer\",\"runtime\":\"codex\",\"terminal\":\"$XH\",\"started_at\":\"$START\",\"calibration\":true}" >/dev/null
orca orchestration check --terminal "$C" --run $RUN --wait --types "worker_done,escalation,question" --timeout-ms 420000 --json > "$W/$ID-raw.txt" 2>&1
python3 -I - "$W/$ID-raw.txt" "$DP" > "$W/$ID.json" <<'EOF' || exit 1
import json,sys
raw=open(sys.argv[1]).read(); i=raw.find('{\n  "id"'); d=json.JSONDecoder(strict=False).raw_decode(raw[i:])[0]; r=d["result"]; m=r["messages"][0]
assert sys.argv[2] in m["payload"], "result is for another dispatch: "+m["payload"]
print(json.dumps({"deliveryId":r["deliveryId"],"id":m["id"],"body":m["body"],"payload":m["payload"],"created_at":m["created_at"],"verdict":(m["body"] or "").split("\n")[0].strip()}, indent=1))
EOF
RH=$(python3 -I -c 'import hashlib,sys; print(hashlib.sha256(open(sys.argv[1]).read().encode()).hexdigest())' "$W/$ID.json"); DEL=$(js "$W/$ID.json" 'd["deliveryId"]')
node "$T" audit-append --log "$LOG" --type result_received --json "$(python3 -I -c 'import json,sys; d=json.load(open(sys.argv[1])); print(json.dumps({"run_id":sys.argv[2],"task_id":sys.argv[3],"dispatch_id":sys.argv[4],"result_hash":sys.argv[5],"outcome":json.loads(d["payload"]).get("outcome"),"role":"reviewer","pass":1,"calibration":True,"candidate_sha":sys.argv[6],"verdict":d["verdict"],"report":d["body"]}))' "$W/$ID.json" $RUN "$TK" "$DP" "$RH" "$CAND")" >/dev/null
node "$T" audit-append --log "$LOG" --type review_pass_one_recorded --json "$(python3 -I -c 'import json,sys; d=json.load(open(sys.argv[1])); print(json.dumps({"run_id":sys.argv[2],"task_id":sys.argv[3],"dispatch_id":sys.argv[4],"candidate_sha":sys.argv[5],"calibration":True,"verdict":d["verdict"],"report":d["body"]}))' "$W/$ID.json" $RUN "$TK" "$DP" "$CAND")" >/dev/null
orca orchestration check --terminal "$C" --run $RUN --ack "$DEL" --timeout-ms 1000 --json >/dev/null
CF=$(find ~/.codex/sessions -name '*.jsonl' -newer "$W/$ID-brief.json" | xargs ls -t 2>/dev/null | head -1); U=$(node "$T" usage-codex --file "$CF"); node "$T" audit-append --log "$LOG" --type usage_recorded --json "$(python3 -I -c 'import json,sys; u=json.loads(sys.argv[1]); print(json.dumps({"run_id":sys.argv[2],"task_id":sys.argv[3],"dispatch_id":sys.argv[4],"runtime":"codex","model":"gpt-6-astra","effort":"high","started_at":sys.argv[5],"ended_at":sys.argv[6],"elapsed_seconds":int((__import__("datetime").datetime.fromisoformat(sys.argv[6].replace("Z","+00:00"))-__import__("datetime").datetime.fromisoformat(sys.argv[5].replace("Z","+00:00"))).total_seconds()),"attempts":1,"measurement_status":u["status"],"source":u.get("source"),"tokens":u.get("tokens"),"cost":None,"calibration":True}))' "$U" $RUN "$TK" "$DP" "$START" "$(date -u +%Y-%m-%dT%H:%M:%SZ)")" >/dev/null
node "$T" audit-append --log "$LOG" --type acceptance_recorded --json "{\"run_id\":\"$RUN\",\"task_id\":\"$TK\",\"dispatch_id\":\"$DP\",\"calibration\":true,\"candidate_sha\":\"$CAND\",\"disposition\":\"calibration candidate; never integrated\",\"verdict\":$(js "$W/$ID.json" 'json.dumps(d["verdict"])')}" >/dev/null
orca orchestration worker-release --dispatch "$DP" --json >/dev/null; orca terminal close --terminal "$XH" --json >/dev/null; orca worktree rm --worktree "path:$RV" --force --json >/dev/null
echo "[calib $ID] $(js "$W/$ID.json" 'd["verdict"]') ($(js "$W/$ID.json" 'd["created_at"]'))"
